  panel.locator('[data-background-id=manual]').click();assert '/api/v1/images/manual' in bg();expect(panel.locator('[data-background-id=manual]')).to_have_attribute('aria-pressed','true');expect(shell.locator('.native-location')).to_have_text('School hallway');assert shell.locator('.ambience i').count()>0;panel.get_by_role('combobox',name='Background fit').select_option('contain');assert layer.evaluate('e=>e.style.backgroundSize')=='contain';panel.get_by_role('slider',name='Horizontal focus').fill('25');assert layer.evaluate('e=>e.style.backgroundPosition')=='25% 50%';panel.get_by_role('slider',name='Zoom %').fill('125');assert layer.evaluate('e=>e.style.transform')=='scale(1.25)';panel.locator('[data-background-id=manual]').scroll_into_view_if_needed();shot('picker');close();assert '/api/v1/images/manual' in bg();go(4);assert '/api/v1/images/manual' in bg();go(5);assert 'data:image' in bg() and '/api/v1/images/manual' not in bg();assert not layer.evaluate('e=>e.style.transform');
  # A pinned backdrop survives scene boundaries, even when rewinding; clearing reveals canonical scene.
