  editor();panel.locator('[data-scenery-source=none]').click();assert not bg();assert not pattern.evaluate('e=>e.style.backgroundImage');assert shell.locator('.ambience i').count()>0;panel.locator('[data-scenery-source=svg]').click();assert 'data:image/svg+xml' in pattern.evaluate('e=>e.style.backgroundImage');panel.locator('[data-scenery-source=story]').click();assert 'data:image' in bg();close();
